using System.Collections;
using UnityEngine;
using UnityEngine.UI;

namespace Astrea;

public class CursorHandler : ReferenceSingleton<CursorHandler>
{
	[SerializeField]
	private RectTransform cursorTransform;

	[SerializeField]
	private Image cursorImage;

	[SerializeField]
	private Vector3 cursorPositionAdjustment;

	private InputManager inputManager => ReferenceSingleton<InputManager>.Instance;

	protected override void Awake()
	{
		if (ReferenceSingleton<CursorHandler>.instance != null)
		{
			Object.Destroy(base.gameObject);
		}
		else
		{
			Object.DontDestroyOnLoad(base.gameObject);
		}
		base.Awake();
	}

	private void Start()
	{
		Cursor.visible = false;
		StartCoroutine(UpdateCursorPosition());
		ToggleCursor(!inputManager.IsJoystickBeingUsed);
	}

	public void ToggleCursor(bool value)
	{
		if (inputManager.IsJoystickBeingUsed)
		{
			if (ReferenceSingleton<AssetsReference>.Instance.GameController.IsReleaseBuildWithDebug)
			{
				cursorImage.enabled = true;
			}
			else
			{
				cursorImage.enabled = false;
			}
		}
		else
		{
			cursorImage.enabled = value;
		}
	}

	private IEnumerator UpdateCursorPosition()
	{
		while (true)
		{
			yield return null;
			cursorTransform.position = Input.mousePosition + cursorPositionAdjustment;
		}
	}

	public void OnInputChangedToMouseToggleObjects(bool value)
	{
		ToggleCursor(value);
	}
}
